// Materialize the ASIM Authentication parser once, bounded to the Zscaler ZPA product predicate, so the
// open-session and closed-session branches below reuse the same result set instead of each triggering a
// separate expansion of the underlying unifying parser.
let AuthEvents = materialize(
    _Im_Authentication
    | where EventVendor =~ "Zscaler" and EventProduct has "Private Access"
);
let open_sessions =
AuthEvents
| where EventType == "Logon" and EventResult == "Success"
| summarize timestampstart = min(TimeGenerated) by TargetUsername, SrcIpAddr
| sort by timestampstart asc;
let closed_sessions =
AuthEvents
| where TimeGenerated > ago(1h)
| where EventType == "Logoff"
| summarize timestampend = max(TimeGenerated) by TargetUsername, SrcIpAddr
| sort by timestampend asc;
open_sessions
| join (closed_sessions) on TargetUsername
| sort by TargetUsername, timestampstart asc
| extend prev_session_closetime = prev(timestampend, 1)
| extend prev_session_starttime = prev(timestampstart, 1)
| extend PreviousSrcIpAddr = prev(SrcIpAddr, 1)
| extend prev_sessionuser = prev(TargetUsername, 1)
| where TargetUsername == prev_sessionuser
| where SrcIpAddr != PreviousSrcIpAddr
| where prev_session_closetime > timestampstart
| project TargetUsername, SrcIpAddr, PreviousSrcIpAddr
| extend IPCustomEntity = SrcIpAddr, AccountCustomEntity = TargetUsername

let threshold = 1000;
_Im_NetworkSession
| where EventVendor =~ "Zscaler" and EventProduct has "Private Access"
| where EventResult == "Failure"
| where DvcAction in ("Deny", "Drop")
// Optional: narrow to the raw ZPA policy-rejection detail if preserved by the pipeline
// | where EventOriginalResultDetails has "REJECTED_BY_POLICY"
| summarize rejected = count() by EventResult, SrcUsername
| where rejected > threshold
| extend AccountCustomEntity = SrcUsername

let dt_lookback = 14d;
let dt_current = 1h;
// Materialize the ASIM Authentication parser once, bounded to the lookback window and the Zscaler ZPA
// logon/success predicate, so the baseline and current branches below reuse the same result set instead
// of each triggering a separate expansion of the underlying unifying parser (which previously caused
// CRT0015).
let AuthEvents = materialize(
    _Im_Authentication
    | where TimeGenerated > ago(dt_lookback)
    | where EventVendor =~ "Zscaler" and EventProduct has "Private Access"
    | where EventType == "Logon" and EventResult == "Success"
);
// Baseline: distinct users who signed in during the ~14-day window preceding the current slice.
let baseline =
AuthEvents
| where TimeGenerated between (ago(dt_lookback) .. ago(dt_current))
| summarize by TargetUsername;
// Current: distinct users who signed in during the most recent hour (matches queryFrequency), so
// baseline and current never overlap.
let current =
AuthEvents
| where TimeGenerated > ago(dt_current)
| summarize by TargetUsername;
// A user in the current slice with no matching TargetUsername in the baseline slice is dormant: they had
// no successful sign-in during the preceding ~14 days.
current
| join kind=leftanti (baseline) on TargetUsername
| extend AccountCustomEntity = TargetUsername

let dt_lookback = 14d;
let dt_current = 1h;
// Materialize the ASIM Authentication parser once, bounded to the lookback window and the Zscaler ZPA
// logon/success predicate, so the baseline and current branches below reuse the same result set instead
// of each triggering a separate expansion of the underlying unifying parser.
let AuthEvents = materialize(
    _Im_Authentication
    | where TimeGenerated > ago(dt_lookback)
    | where EventVendor =~ "Zscaler" and EventProduct has "Private Access"
    | where EventType == "Logon" and EventResult == "Success"
);
// Baseline: distinct users who signed in during the ~14-day window preceding the current slice.
let baseline =
AuthEvents
| where TimeGenerated between (ago(dt_lookback) .. ago(dt_current))
| summarize by TargetUsername;
// Current: distinct users who signed in during the most recent hour (matches queryFrequency), so
// baseline and current never overlap.
let current =
AuthEvents
| where TimeGenerated > ago(dt_current)
| summarize by TargetUsername;
// A user in the current slice with no matching TargetUsername in the baseline slice is new: they had no
// sign-in during the preceding ~14 days.
current
| join kind=leftanti (baseline) on TargetUsername
| extend AccountCustomEntity = TargetUsername

let dt_lookback = 14d;
let dt_current = 1h;
// Materialize the ASIM Network Session parser once, bounded to the lookback window and the Zscaler ZPA
// product predicate, so the baseline and current branches below reuse the same result set instead of each
// triggering a separate expansion of the underlying unifying parser.
let NetworkEvents = materialize(
    _Im_NetworkSession
    | where TimeGenerated > ago(dt_lookback)
    | where EventVendor =~ "Zscaler" and EventProduct has "Private Access"
);
// Baseline: distinct (user, country) pairs allowed during the ~14-day window preceding the current slice.
let baseline =
NetworkEvents
| where TimeGenerated between (ago(dt_lookback) .. ago(dt_current))
| where DvcAction == "Allow"
| summarize by SrcUsername, SrcGeoCountry;
// Current: distinct (user, country) pairs seen in the most recent hour (matches queryFrequency, not
// filtered on DvcAction as in the upstream rule), so baseline and current never overlap.
let current =
NetworkEvents
| where TimeGenerated > ago(dt_current)
| where isnotempty(SrcGeoCountry)
| summarize by SrcUsername, SrcGeoCountry;
// A (user, country) pair in the current slice with no matching pair in the baseline slice is new for that
// specific user; keying the leftanti join on both SrcUsername and SrcGeoCountry ensures a different user's
// history from that country cannot suppress this detection.
current
| join kind=leftanti (baseline) on SrcUsername, SrcGeoCountry
| extend AccountCustomEntity = SrcUsername

let dt_lookback = 14d;
let dt_current = 1h;
// Materialize the ASIM Network Session parser once, bounded to the lookback window and the Zscaler ZPA
// product predicate, so the baseline and current branches below reuse the same result set instead of each
// triggering a separate expansion of the underlying unifying parser.
let NetworkEvents = materialize(
    _Im_NetworkSession
    | where TimeGenerated > ago(dt_lookback)
    | where EventVendor =~ "Zscaler" and EventProduct has "Private Access"
);
// Baseline: distinct (user, IP) pairs allowed during the ~14-day window preceding the current slice.
let baseline =
NetworkEvents
| where TimeGenerated between (ago(dt_lookback) .. ago(dt_current))
| where DvcAction == "Allow"
| summarize by SrcUsername, SrcIpAddr;
// Current: distinct (user, IP) pairs seen in the most recent hour (matches queryFrequency, not filtered
// on DvcAction as in the upstream rule), so baseline and current never overlap.
let current =
NetworkEvents
| where TimeGenerated > ago(dt_current)
| where isnotempty(SrcIpAddr)
| summarize by SrcUsername, SrcIpAddr;
// A (user, IP) pair in the current slice with no matching pair in the baseline slice is new for that
// specific user; keying the leftanti join on both SrcUsername and SrcIpAddr ensures a different user's
// history from that IP address cannot suppress this detection.
current
| join kind=leftanti (baseline) on SrcUsername, SrcIpAddr
| extend IPCustomEntity = SrcIpAddr, AccountCustomEntity = SrcUsername

let dt_lookBack = 24h;
let time_treshhold = timespan(08:00:00);
// Materialize the ASIM Network Session parser once, bounded to the lookback window and the Zscaler ZPA
// product predicate, so the open-session and closed-session branches below reuse the same result set
// instead of each triggering a separate expansion of the underlying unifying parser.
let NetworkEvents = materialize(
    _Im_NetworkSession
    | where TimeGenerated > ago(dt_lookBack)
    | where EventVendor =~ "Zscaler" and EventProduct has "Private Access"
);
let open_sessions =
NetworkEvents
| where EventSubType == "Start"
| summarize timestampstart = min(TimeGenerated) by SrcUsername, SrcIpAddr, NetworkSessionId
| sort by timestampstart asc;
let closed_sessions =
NetworkEvents
| where EventSubType == "End"
| summarize timestampend = max(TimeGenerated) by SrcUsername, SrcIpAddr, NetworkSessionId
| sort by timestampend asc;
open_sessions
| join (closed_sessions) on SrcUsername, SrcIpAddr, NetworkSessionId
| extend duration = timestampend - timestampstart
| where duration > time_treshhold
| where SrcUsername !has "ZPA LSS"
| sort by timestampstart asc
| extend IPCustomEntity = SrcIpAddr, AccountCustomEntity = SrcUsername
